from collections import Counter, deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = all(grid[y][x] == color for y in range(r0,r1+1) for x in range(c0,c1+1)
                            if y in (r0,r1) or x in (c0,c1))
            interior_bg = all(grid[y][x] == background for y in range(r0+1,r1) for x in range(c0+1,c1))
            if perimeter and interior_bg:
                fill = 2 if (r1-r0+1, c1-c0+1) == (4,4) else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x] = fill
    return out

